{
  "shot": {
    "composition": "中景镜头，使用50mm标准镜头，浅景深，聚焦于男孩与桌面上的骷髅头，背景书架与烛光虚化，营造神秘氛围。",
    "camera_motion": "静态镜头，无运镜，保持稳定，以突出主体与环境的静谧感。",
    "frame_rate": "24fps",
    "film_grain": "Kodak 520D 数字模拟，轻微颗粒感，增强复古电影质感"
  },
  "subject": {
    "description": "一个10岁左右的欧洲男孩，金发微卷，皮肤白皙，眼神专注，表情略带沉思，穿着深色夹克，内搭蓝色衬衫，坐在木桌前。",
    "wardrobe": "深色皮质夹克，内搭蓝色衬衫，袖口略卷，领口微敞，无其他配饰。"
  },
  "scene": {
    "location": "一座古旧的图书馆或书房，墙壁上挂满书籍与古老器具，角落有骷髅头与地球仪。",
    "time_of_day": "夜晚",
    "environment": "室内，光线昏暗，仅靠烛台与灯笼照明，空气中弥漫着淡淡的灰尘与纸张气味，背景书架高耸，布满灰尘与蛛网。"
  },
  "visual_details": {
    "action": "男孩左手托腮，右手轻抚书页，眼神凝视书本，似乎在深思或阅读，偶尔微微点头。",
    "props": [
      "一本打开的厚重古籍，封面磨损，书页泛黄",
      "一个大型人头骨骷髅头，放置在桌左侧",
      "一个古旧地球仪，位于男孩右后方",
      "多个玻璃烛台，内有燃烧的蜡烛，散发微光",
      "一个金属灯笼，悬挂在桌角，烛光映照出柔和光影"
    ]
  },
  "cinematography": {
    "lighting": "主要光源来自烛台与灯笼，光线柔和偏暖，形成明暗对比，阴影部分营造神秘感，背景由烛光与书架阴影构成层次感。",
    "tone": "神秘、沉静、略带诡异，仿佛在讲述一个古老而深邃的故事。"
  },
  "color_palette": "深棕色、暗金色、灰白色与黑色为主，烛光投射出暖黄色高光，整体色调低饱和度，强化神秘与复古氛围。"
}

